# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: what makes a chat turn an "inline" one (Alt+I in an editor, a widget's form, the
#          Terminal; "/assign"). Inline is a category, not a second AI: the turn goes through
#          the same Session.ask as the chat box, on the same agent and the same history. An
#          Inline only says what differs: the form the answer must have (its output type,
#          for a widget the tool's own inputs), the rules and reference for writing it, its
#          check, and the label it is logged, costed and shown under (inline-edit, ...).
# Usage: await session.ask(message, inline=Inline(label="edit", output_type=InlineEdit, ...))
#        -> AiResult with .output. InlineMode is the capability Session.ask adds for such a
#        turn: no tools, and an answer that fails the check goes back to the model.
# Spec:  spec/services/ui/inline_ai.md
# ---------------------------------------------------------------------------
from __future__ import annotations

import dataclasses
import inspect
from collections.abc import Awaitable, Callable
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from pydantic_ai import ModelRetry
from pydantic_ai.capabilities import AbstractCapability

if TYPE_CHECKING:
    from pydantic_ai import RunContext

__all__ = ["LABELS", "MAX_FIXES", "SHARED_RULES", "Check", "Inline", "InlineMode", "agent_name", "asked_in"]

# times an answer that fails its check is sent back to the model to fix; after that it is
# returned as it is (the caller shows it, or refuses it)
MAX_FIXES = 2
# The labels: what each is for (the debug panel's Agents tab) and where its rules are written.
LABELS: dict[str, tuple[str, str]] = {
    "edit": ("Inline chat in a cell or SQL box (Alt+I)", "services/ui/ui/inline_edit.py"),
    "fill": ("Inline chat in a widget's tool form: fills its inputs (Alt+I)", "services/ui/ui/inline_fill.py"),
    "terminal": (
        "Inline chat in the Terminal: writes a command at your prompt (Alt+I)",
        "services/ui/ui/inline_terminal.py",
    ),
    "assign": ("/assign: writes the code of a new variable (you run it)", "services/ui/ui/assign.py"),
}
# said to the model on every inline turn, before the place's own rules
SHARED_RULES = " ".join(
    [
        "This message was sent from inside the app (the place is named in it), not typed in the chat box:",
        "answer in one step with the structured output asked for. You have no tools for it and can't",
        "look anything up. It is part of the same conversation as the chat.",
    ]
)

# an answer's problem as the text sent back to the model ("" = it is fine); may be async
Check = Callable[[Any], "str | Awaitable[str]"]


def agent_name(label: str) -> str:
    """How a label's turns are named: the debug log record's source, Logfire's spans and so
    the Spend tab's split by agent, eg 'inline-edit'.
    """
    return f"inline-{label}"


def asked_in(where: str) -> str:
    """The first line of an inline turn's message: where it was asked. It stays in the chat's
    history, so the agent later knows the message didn't come from the chat box.
    """
    return f"(Asked with the inline AI in {where}, not in the chat box.)"


@dataclass
class Inline:
    """What makes one turn an inline one (see the file's purpose)."""

    label: str
    """A key of LABELS: edit | fill | terminal | assign."""
    output_type: Any
    """The form the answer must have."""
    rules: str
    """How to write that answer: instructions for this turn only."""
    instruction: str
    """What the user typed (the log's prompt and the chat row's text)."""
    where: str
    """The place, for the chat row: 'a Python cell', 'the Terminal'."""
    answer: Callable[[Any], str]
    """The output as text: the chat row's fold and the session log's reply."""
    context: str = ""
    """Reference for this turn (tables, variables, the terminal's screen): sent as
    instructions, so it is not kept in the chat's history and not sent again later."""
    check: Check | None = None
    name: str = ""
    """The log record's name, eg 'inline edit (sql)'; the label's by default."""
    added: str = ""
    """What "@" mentions put in the message (the log shows it)."""
    row: bool = True
    """Add a row to the chat pane; False when the place draws its own ("/assign")."""

    @property
    def agent_name(self) -> str:
        return agent_name(self.label)

    @property
    def title(self) -> str:
        return self.name or self.agent_name.replace("-", " ")

    def instructions(self) -> list[str]:
        return [text for text in (SHARED_RULES, self.rules, self.context) if text]


@dataclass
class InlineMode(AbstractCapability[Any]):
    """Added by Session.ask for an inline turn: no tools, and the answer's check.

    Made anew for each turn (it counts that turn's fixes).
    """

    check: Check | None = None
    fixes: int = 0
    """Answers sent back to the model so far because they failed the check."""

    async def before_model_request(self, ctx: RunContext[Any], request_context: Any) -> Any:  # noqa: ARG002  # the hook's signature
        """No tools in an inline turn: not the agent's own, not a capability's the chat loaded,
        not the one that loads them (spec: one request, from what it is given).
        """
        parameters = request_context.model_request_parameters
        request_context.model_request_parameters = dataclasses.replace(parameters, function_tools=[])
        return request_context

    async def after_output_validate(
        self,
        ctx: RunContext[Any],  # noqa: ARG002  # the hook's signature
        *,
        output_context: Any,  # noqa: ARG002  # the hook's signature
        output: Any,
    ) -> Any:
        if self.check is None or self.fixes >= MAX_FIXES:
            return output
        problem = self.check(output)
        if inspect.isawaitable(problem):
            problem = await problem
        if problem:
            self.fixes += 1
            raise ModelRetry(problem)
        return output
